# DRAFT figure for round 17
import json, numpy as np, matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
r=json.load(open('results.json')); a=np.array(r['angles_deg'])
fig,(L,R)=plt.subplots(1,2,figsize=(13,5.4))
L.plot(a,r['min_shannon'],'o-',color='#1565c0',lw=2.5,label='least total uncertainty, Shannon (k = 0)')
L.plot(a,np.array(r['min_tsallis2'])*np.max(r['min_shannon'])/np.max(r['min_tsallis2']),'s--',color='#ef6c00',label='same with the law at k = -1 (Tsallis q = 2), rescaled')
L.plot(a,r['MU_bound'],':',color='#555',lw=2,label='Maassen–Uffink bound (1988)')
L.axvline(90,color='#2e7d32',alpha=.4,lw=8); L.text(93,.12,'90°: full 1 bit\nof uncertainty\n= the flips anticommute',color='#2e7d32',fontsize=10)
L.set_xlabel('angle between the two flips (degrees)'); L.set_ylabel('bits'); L.set_xticks(range(0,181,30)); L.set_ylim(-.03,1.25)
L.legend(loc='upper left',fontsize=8.8); L.set_title('Most uncertainty, whatever the dial, sits at the anticommuting sign',fontsize=11)
t=np.linspace(0,2*np.pi,200)
R.plot(np.cos(t),np.sin(t),color='#9e9e9e',lw=2); R.plot(np.cos(t)+2.8,np.sin(t),color='#1565c0',lw=2)
R.plot(np.cos(t)*.35+2.8,np.sin(t)*1.0*0+np.sin(t)*.0+np.sin(t)*0,alpha=0)
for (dx,dy,lab) in ((0,1,'Z'),(1,0,'X')): R.annotate('',(dx,dy),(0,0),arrowprops=dict(arrowstyle='->',lw=2.5,color='#9e9e9e')); R.text(dx*1.12-.05,dy*1.12,lab,fontsize=12)
for (dx,dy,lab) in ((0,1,'Z'),(1,0,'X'),(-.55,-.45,'Y')): R.annotate('',(2.8+dx,dy),(2.8,0),arrowprops=dict(arrowstyle='->',lw=2.5,color='#1565c0')); R.text(2.8+dx*1.15-.05,dy*1.15,lab,fontsize=12,color='#1565c0')
R.text(-1,-1.45,'real numbers: room for\n2 fully 50/50 questions',fontsize=10.5,color='#555'); R.text(1.8,-1.45,'complex numbers (with i): room\nfor 3 fully 50/50 questions',fontsize=10.5,color='#1565c0')
R.set_aspect('equal'); R.axis('off'); R.set_xlim(-1.4,4.2); R.set_ylim(-1.8,1.5); R.set_title('The sign needs no i; a third 50/50 question does',fontsize=11)
fig.suptitle('DRAFT  round 17: maximal uncertainty is the anticommuting sign; i appears only with the third question',fontsize=12,color='#b71c1c')
fig.tight_layout(); fig.savefig('us1_sign.png',dpi=130)
